import { useState, useEffect, RefObject } from "react";

export function useIsWider(ref: RefObject<HTMLElement | null>, pixels: number) {
  const [isWider, setIsWider] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => {
      setIsWider(entry.contentRect.width >= pixels);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref, pixels]);

  return isWider;
}

import { useState, useEffect } from "react";

export function useIsViewportWider(pixels: number) {
  const [isWider, setIsWider] = useState(false);

  useEffect(() => {
    const mql = window.matchMedia(`(min-width: ${pixels}px)`);
    setIsWider(mql.matches);
    const handler = (e: MediaQueryListEvent) => setIsWider(e.matches);
    mql.addEventListener("change", handler);
    return () => mql.removeEventListener("change", handler);
  }, [pixels]);

  return isWider;
}

import { useCallback, useRef } from "react";

interface UseLongPressOptions {
  delay?: number;
}

export function useLongPress(
  callback: () => void,
  { delay = 500 }: UseLongPressOptions = {},
) {
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startPosRef = useRef<{ x: number; y: number } | null>(null);

  const cancel = useCallback(() => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    startPosRef.current = null;
  }, []);

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      if (e.pointerType !== "touch") return;
      startPosRef.current = { x: e.clientX, y: e.clientY };
      timerRef.current = setTimeout(() => {
        timerRef.current = null;
        callback();
      }, delay);
    },
    [callback, delay],
  );

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!startPosRef.current) return;
      const dx = e.clientX - startPosRef.current.x;
      const dy = e.clientY - startPosRef.current.y;
      if (Math.sqrt(dx * dx + dy * dy) > 10) cancel();
    },
    [cancel],
  );

  const onContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
  }, []);

  return {
    onPointerDown,
    onPointerUp: cancel,
    onPointerLeave: cancel,
    onPointerCancel: cancel,
    onPointerMove,
    onContextMenu,
  };
}

