interface MessageActionsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onReaction?: (emoji: string) => void;
  onCopy?: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
}

export function MessageActionsDialog({
  open,
  onOpenChange,
  onReaction,
  onCopy,
  onEdit,
  onDelete,
}: MessageActionsDialogProps) {
  const hasActions = !!onCopy || !!onEdit || !!onDelete;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-xs">
        <DialogHeader>
          <DialogTitle className="sr-only">Message actions</DialogTitle>
          <DialogDescription className="sr-only">
            React to this message or choose an action
          </DialogDescription>
        </DialogHeader>
        {onReaction && (
          <div className="flex gap-0.5 flex-wrap">
            {DEFAULT_REACTIONS.map((emoji) => (
              <Button
                key={emoji}
                variant="ghost"
                size="icon"
                className="size-10 text-xl"
                onClick={() => {
                  onReaction(emoji);
                  onOpenChange(false);
                }}
              >
                {emoji}
              </Button>
            ))}
          </div>
        )}
        {hasActions && (
          <>
            {onReaction && <div className="border-t" />}
            <div className="flex flex-col">
              {onCopy && (
                <Button
                  variant="ghost"
                  className="justify-start gap-2"
                  onClick={() => {
                    onCopy();
                    onOpenChange(false);
                  }}
