                  <CopyIcon className="size-4" />
                  Copy
                </Button>
              )}
              {onEdit && (
                <Button
                  variant="ghost"
                  className="justify-start gap-2"
                  onClick={() => {
                    onOpenChange(false);
                    onEdit();
                  }}
                >
                  <PencilIcon className="size-4" />
                  Edit
                </Button>
              )}
              {onDelete && (
                <Button
                  variant="ghost"
                  className="justify-start gap-2 text-destructive hover:text-destructive"
                  onClick={() => {
                    onOpenChange(false);
                    onDelete();
                  }}
                >
                  <Trash2Icon className="size-4" />
                  Delete
                </Button>
              )}
            </div>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
